const FILTERS={work:["ids","status"],review:["ids","target","judgment","subject_paths"],finding:["ids","review_ids","state","subject_paths"],blocker:["ids","state","subject_paths"],evidence:["ids","result","subject_paths"],decision:["ids","subject_paths"],model:["ids","subject_paths"],applicability:["paths","value"],verify:[],decisions:[],proposal:[],plan:[],activity:[]};
const SUMMARY={work:["id","status","owner"],review:["id","target","reviewer","subjects","judgment"],finding:["id","reporter","owner","subjects","state","required_outcome"],blocker:["id","reporter","owner","subjects","state","required_outcome"],evidence:["id","actor","subjects","result"],decision:["id","actor","subjects","source_refs"],verify:["schema_version","change_id","verifier","subjects","evidence_refs","review_refs","outcome"],decisions:["schema_version","change_id"]};
const FULL={work:["id","status","owner","requirement_refs"],review:["schema_version","change_id","id","target","reviewer","contributors","independence_basis","subjects","judgment","body"],finding:["id","reporter","owner","subjects","evidence","required_outcome","state","resolution","origin"],blocker:["id","reporter","owner","subjects","evidence","required_outcome","state","resolution","origin"],evidence:["id","actor","subjects","result","procedure","summary"],decision:["id","actor","subjects","rationale","source_refs"],verify:[...SUMMARY.verify,"body"],decisions:[...SUMMARY.decisions,"decisions","body"]};
const PROJECT_FIELDS=Object.fromEntries(['review','verify'].map(kind=>[kind,Object.keys(RECORDS_V3_SCHEMA.$defs[kind].properties).sort()]));
const FULL_V3={...FULL,review:PROJECT_FIELDS.review.filter(f=>f!=='findings'),verify:PROJECT_FIELDS.verify,finding:FULL.finding.filter(f=>f!=='origin')};
