function inspectSubjects(s){if(!s.paths.length||s.paths.length>256||new Set(s.paths).size!==s.paths.length)stop("invalid-input");s.paths.forEach(safePath);const reader=new RecordFiles(s.root),subjects=[],contents=[],observations=[];for(const path of s.paths){let identity,content;if(s.content==="full"){const bytes=reader.read(path,s.maxBytes);identity=digest(bytes);try{content=bytes===null?null:new TextDecoder("utf-8",{fatal:true,ignoreBOM:true}).decode(bytes);}catch{stop("invalid-input");}contents.push({path,content});}else identity=reader.hash(path);subjects.push({path,identity});if(identity===null)observations.push({code:"subject-drift",path,message:"Record store: subject-drift."});fit({schema_version:2,operation:s.operation,status:"inspected",claim:"storage-only",data:{subjects,...(s.content==="full"?{contents}:{})},...(observations.length?{observations,observations_scope:"selected-subjects"}:{})},s);}const result={schema_version:2,operation:s.operation,status:"inspected",claim:"storage-only",data:{subjects}};if(s.content==="full")result.data.contents=contents;if(observations.length){result.observations=observations;result.observations_scope="selected-subjects";}return fit(result,s);}
export function executeRecordingQueryCli(argv,options={}){let s=args(argv),snapshot;try{if(s.invalid)stop("invalid-input");if(s.help)return{result:null,json:"",human:`${s.operation}: inspect explicitly selected stored information (storage-only). Requires --root${s.operation==="subject.inspect"?" and --path":" and --change"}. No workflow approval.${["review.show","verify.show"].includes(s.operation)?" Optional --fields NAME[,NAME...] selects exact v3 stored fields and reports omissions.":""}\n`,exitCode:0,format:s.format};if(s.operation==="subject.inspect")return{...inspectSubjects(s),format:s.format};let selection;if(s.operation==="context")selection=normalize(parseRequestJSON(options.input??(options.readInput??stdin)()));else if(s.operation.endsWith(".show")&&s.operation!=="observations.show"){const kind=s.operation.split(".")[0];selection=normalize({schema_version:1,select:[{kind,where:["verify","decisions"].includes(kind)?{}:{ids:[s.id],...(kind==="finding"?{review_ids:[s.review]}:{})}}]});}
 if(s.fields)selection.fields=s.fields;
 const output=withRecordSnapshot(s.root,s.changeId,current=>{snapshot={...current,scan:scanObservations(current)};if(s.fields&&Object.keys(snapshot.set).length&&snapshot.format.version!==3)stop("unsupported-contract");if(s.expected!==undefined&&(s.expected==="absent"?null:s.expected)!==snapshot.revision)stop("identity-conflict");if(s.operation==="status")return status(s,snapshot);if(s.operation==="observations.show")return observationPage(s,snapshot);return page(s,snapshot,selection,s.operation!=="context");},options);return{...output,format:s.format};
 }catch(e){const code=e.recordStoreCode??(e.code?"io-failure":"invalid-input"),status=({"identity-conflict":"conflict","store-busy":"busy","recovery-needed":"recovery-required"}[code]??"rejected"),result={schema_version:snapshot&&e.snapshotVerified&&Object.keys(snapshot.set).length&&snapshot.format.version===3?3:2,operation:s.operation,status,claim:"storage-only",errors:[{code,message:code==="limit-exceeded"?"Response limit exceeded; narrow selection, request summary, or increase --max-bytes.":`Record: ${code}.`}]};if(s.changeId&&s.operation!=="subject.inspect")result.change_id=s.changeId;if(snapshot&&e.snapshotVerified){if(snapshot.revision!==null)result.revision=snapshot.revision;const summary=snapshot.scan.summary();if(summary)result.observation_summary=summary;}if(status==="recovery-required"&&e.transaction)result.transaction=e.transaction;return{...serializePrimary(result),format:s.format};}}
